using Cultivation.Domain;
using Cultivation.Simulation;
using Cultivation.Persistence;

internal static class SectGatherLifecycleTests
{
    private static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    private static WorldState World(){var w=LifeEventScenario.Create();for(int n=0;n<w.Characters.Count;n++)if(w.Characters[n].Id is "player" or "npc:00"){var a=w.Characters[n];w.Characters[n]=a with {DemoLocationId="grove",HexPosition=RegionGeometry.Resolve(w.HexMap!,a,"grove")};w.SectWorkAssignments.Add(new(a.Id,"sect","herb"));}return w;}
    private static ActionIntent Gather(string id,string actor="player")=>new(id,actor,"grove","herb",1,0,actor=="player"?DecisionSource.Player:DecisionSource.Npc,ActionKind.SectGather);
    public static IEnumerable<(string Name,Action Body)> Cases=>new (string,Action)[]{
        ("R2 sect gather reserves and completes once",()=>{var w=World();long stock=Inventory.Balance(w,"grove","herb");var e=new SimulationEngine(w);e.Submit(Gather("sg"));e.AdvanceTo(0);w=e.Snapshot();var a=w.Time!.ActionRuntime!.Actions["sg"];var r=w.Time.ActionRuntime.Reservations["sg:sect-gather-resource"];Check(a.Phase==ActionPhase.Running&&r.Remaining==1&&Inventory.Balance(w,"grove","herb")==stock-1,"Missing reservation");long due=w.Scheduled.Single(t=>t.Intent.Id==a.Id).DueAtSeconds!.Value;e.AdvanceTo(due);w=e.Snapshot();Check(w.Time!.ActionRuntime!.Actions[a.Id].Phase==ActionPhase.Completed&&w.Time.ActionRuntime.Reservations[r.Id].Consumed==1&&w.SectWorkReceipts.Count(x=>x.Id==a.Id)==1,"Wrong settlement");e.Submit(Gather("sg"));e.AdvanceTo(due);Check(e.Snapshot().SectWorkReceipts.Count(x=>x.Id==a.Id)==1,"Duplicate settlement");}),
        ("R2 sect gatherers compete for last herb",()=>{var w=World();long stock=Inventory.Balance(w,"grove","herb");Check(stock>1,"Missing stock");w.Ledger.Add(new(w.NextSequence++,0,"fixture","grove","sect","herb",stock-1,"FixtureTransfer"));var e=new SimulationEngine(w);e.Submit(Gather("first"));e.Submit(Gather("second","npc:00"));e.AdvanceTo(0);w=e.Snapshot();Check(w.Time!.ActionRuntime!.Actions.ContainsKey("first")&&!w.Time.ActionRuntime.Actions.ContainsKey("second")&&!w.Time.Charges.Any(c=>c.ActionId=="second"),"Double reservation or AP charge");}),
        ("R2 sect gather requires assignment",()=>{var w=World();w.SectWorkAssignments.RemoveAll(a=>a.ActorId=="player");var e=new SimulationEngine(w);e.Submit(Gather("not-accepted"));e.AdvanceTo(0);w=e.Snapshot();Check(!w.Time!.ActionRuntime!.Actions.ContainsKey("not-accepted")&&w.Events.Any(x=>x.ActionId=="not-accepted"&&x.Kind=="Rejected"),"Unaccepted work started");}),
        ("R2 sect gather supports player and NPC",()=>{var e=new SimulationEngine(World());e.Submit(Gather("player-work"));e.Submit(Gather("npc-work","npc:00"));e.AdvanceTo(0);var w=e.Snapshot();Check(w.Time!.ActionRuntime!.Reservations.ContainsKey("player-work:sect-gather-resource")&&w.Time.ActionRuntime.Reservations.ContainsKey("npc-work:sect-gather-resource"),"Missing reservations");long due=w.Scheduled.Where(t=>t.Intent.Id is "player-work" or "npc-work").Max(t=>t.DueAtSeconds!.Value);e.AdvanceTo(due);w=e.Snapshot();Check(w.Time!.ActionRuntime!.Actions["player-work"].Phase==ActionPhase.Completed&&w.Time.ActionRuntime.Actions["npc-work"].Phase==ActionPhase.Completed,"Work not complete");}),
        ("R2 former member produces for sect without contribution",()=>{var e=new SimulationEngine(World());e.Submit(Gather("exit","npc:00"));e.AdvanceTo(0);var w=e.Snapshot();long due=w.Scheduled.Single(t=>t.Intent.Id=="exit").DueAtSeconds!.Value;int n=w.Characters.FindIndex(c=>c.Id=="npc:00");w.Characters[n]=w.Characters[n] with{OrganizationId=null,Position=OrganizationPosition.None};SectFacilityActions.ClearMembership(w,"npc:00","test-exit");WorldPeriodEvents.Sync(w,new EventScheduler(w.Time!.DiscreteEvents!));e=new SimulationEngine(w);e.AdvanceTo(due);w=e.Snapshot();Check(w.Time!.ActionRuntime!.Actions["exit"].Phase==ActionPhase.Completed&&w.SectWorkReceipts.Single(x=>x.Id=="exit").Contribution==0,"Exit settlement incorrect");}),
        ("R2 sect gather rejects missing reservation",()=>{var e=new SimulationEngine(World());e.Submit(Gather("forged"));e.AdvanceTo(0);var w=e.Snapshot();w.Time!.ActionRuntime!.Reservations.Remove("forged:sect-gather-resource");bool rejected=false;try{WorldIntegrity.Validate(w);}catch(InvalidDataException){rejected=true;}Check(rejected,"Missing reservation accepted");}),
        ("R2 sect gather survives JSON and SQLite",()=>{var e=new SimulationEngine(World());e.Submit(Gather("persist"));e.AdvanceTo(0);var w=e.Snapshot();long due=w.Scheduled.Single(t=>t.Intent.Id=="persist").DueAtSeconds!.Value;string dir=Path.Combine(Path.GetTempPath(),"r2-sect-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{foreach(IWorldStore store in new IWorldStore[]{new JsonWorldStore(),new SqliteWorldStore()}){string path=Path.Combine(dir,store.GetType().Name);store.Save(path,w);var a=new SimulationEngine(w);var b=new SimulationEngine(store.Load(path));a.AdvanceTo(due);b.AdvanceTo(due);Check(WorldCodec.Digest(a.Snapshot())==WorldCodec.Digest(b.Snapshot()),"Store continuation differs");}}finally{foreach(string file in Directory.GetFiles(dir))File.Delete(file);Directory.Delete(dir);}}),
        ("R2 legacy sect gathering remains unchanged",()=>{var w=RegionalWorldScenario.Create();int n=w.Characters.FindIndex(c=>c.Id=="player");var actor=w.Characters[n];w.Characters[n]=actor with{DemoLocationId="grove",HexPosition=RegionGeometry.Resolve(w.HexMap!,actor,"grove")};w.SectWorkAssignments.Add(new("player","sect","herb"));var e=new SimulationEngine(w);e.Submit(Gather("legacy"));e.AdvanceTo(0);w=e.Snapshot();Check(!w.Time!.ActionRuntime!.Actions.ContainsKey("legacy"),"Legacy mode changed");var t=w.Scheduled.Single(t=>t.Intent.Id=="legacy");e.AdvanceTo(t.DueTick*DiscreteTime.SecondsPerStep(w));Check(e.Snapshot().SectWorkReceipts.Count(x=>x.Id=="legacy")==1,"Legacy work failed");})
    };
}
